function raw_route_paper(string $id,string $en,string $status,int $revision,string $teacher,int $original,int $peer,int $policy,string $at):void{query('INSERT INTO term_papers (id,enrollment_id,week_index,task_kind,revision,document_json,word_count,status,originality,peer_consent,consent_version,teacher_status,updated_at,submitted_at) VALUES (?,?,0,?,?,?,?,?,?,?,?,?,?,?)',[$id,$en,'opening',$revision,'{}',300,$status,$original,$peer,$policy,$teacher,$at,$status==='submitted'?$at:null]);}
