expect_flex(!term_allocate_batch($guardOff,0,'opening',$now+10),'Invalid or private records must not create a pair.');expect_flex(term_allocate_batch($guardOff,0,'opening',$thu,true),'Only the valid singleton should receive service routing.');foreach(['private-draft','no-sharing','old-revision','integrity-hold','old-consent','no-originality'] as $id)expect_flex(term_peer_route($id)===null,'An invalid queue entry was exposed: '.$id);
